{
  "stg_google_ads__account_history": {
    "items": [
      {
        "problem": "The most-recent flag still orders by a timestamp cast that was demonstrated to return NULL for the source format, so it may select an arbitrary history record.",
        "about": "data",
        "evidence_in_work": "row_number() over(partition by id order by try_cast(updated_at AS TIMESTAMPTZ) desc nulls last)=1",
        "source": "Cleaned and validated Google Ads account configuration data with current state tracking",
        "importance": 5,
        "reason": "The parsing repair changed the selected timestamp but not the window ordering, potentially giving every downstream model stale account attributes."
      },
      {
        "problem": "The most-recent flag is assigned before invalid records are removed, potentially leaving an account with valid history but no surviving current record.",
        "about": "requirement",
        "evidence_in_work": "row_number() ... =1 is_most_recent_record ... FROM validated WHERE ... updated_at <= current_timestamp",
        "source": "updated_at <= CURRENT_TIMESTAMP; on_failure: delete_row",
        "importance": 3,
        "reason": "A rejected record can consume the current-record position and prevent otherwise valid account attributes from joining downstream."
      }
    ],
    "fewer_reason": "Only two distinct, supported concerns were found for this table."
  },
  "stg_google_ads__account_stats": {
    "items": [
      {
        "problem": "The retained network/device rows may not constitute one daily account record, but their actual grain was not checked before downstream daily windows were applied.",
        "about": "data",
        "evidence_in_work": "staging.stg_google_ads__account_stats 10000; marts.google_ads__account_report 9674",
        "source": "raw.account_stats_data includes ad_network_type and device",
        "importance": 4,
        "reason": "The reduction in the daily report indicates repeated daily keys that can materially change downstream trends and account totals."
      },
      {
        "problem": "The explicitly required full three-CTE implementation for account statistics is replaced with a two-CTE projection with no metrics_calculated step.",
        "about": "requirement",
        "evidence_in_work": "WITH base AS (...) , validated AS (...) SELECT * FROM validated",
        "source": "FULL Tables (3-CTE): account_stats, keyword_stats (these include complex calculated performance metrics)",
        "importance": 2,
        "reason": "An expressly documented processing stage is absent, although the supplied column list does not specify its additional calculations."
      }
    ],
    "fewer_reason": "Only two supported concerns were identifiable without inventing additional staging validations."
  },
  "stg_google_ads__campaign_history": {
    "items": [
      {
        "problem": "The current campaign record is selected using the unrepaired TIMESTAMPTZ cast rather than the working timestamp parser.",
        "about": "data",
        "evidence_in_work": "order by try_cast(updated_at AS TIMESTAMPTZ) desc nulls last",
        "source": "Cleaned and validated Google Ads campaign configuration data with hierarchical relationships",
        "importance": 5,
        "reason": "NULL sort keys make current campaign attributes arbitrary whenever an ID has multiple history records."
      },
      {
        "problem": "Invalid advertising-channel values are nullified and then their entire records are deleted instead of being retained with a NULL field.",
        "about": "requirement",
        "evidence_in_work": "case when advertising_channel_type in (...) then advertising_channel_type end ... and advertising_channel_type is not null",
        "source": "advertising_channel_type IN ('SEARCH', 'DISPLAY', 'SHOPPING', 'VIDEO', 'MULTI_CHANNEL'); on_failure: nullify_field",
        "importance": 4,
        "reason": "This removes campaign dimensions and can eliminate matching campaign facts from cohort analysis."
      },
      {
        "problem": "The date filters admit a missing start_date even when a populated end_date cannot satisfy the specified comparison.",
        "about": "requirement",
        "evidence_in_work": "(start_date is null or start_date <= current_date) and (end_date is null or start_date is null or end_date >= start_date)",
        "source": "start_date <= CURRENT_DATE; end_date IS NULL OR end_date >= start_date",
        "importance": 2,
        "reason": "The explicit NULL exemptions broaden the accepted row set beyond a literal implementation of the validation rules."
      },
      {
        "problem": "The current-record position is assigned before campaign validation, so rejecting that row can leave no current campaign snapshot.",
        "about": "requirement",
        "evidence_in_work": "row_number() ... =1 is_most_recent_record ... SELECT * FROM validated WHERE ...",
        "source": "start_date <= CURRENT_DATE; on_failure: delete_row",
        "importance": 3,
        "reason": "Valid older history can survive without ever being available to the latest-history joins."
      }
    ],
    "fewer_reason": "Four distinct concerns are supported by the implementation and contract."
  },
  "stg_google_ads__campaign_stats": {
    "items": [
      {
        "problem": "The campaign identifier is taken from base_campaign rather than id without establishing which raw field represents the required campaign key.",
        "about": "data",
        "evidence_in_work": "CAST(base_campaign AS VARCHAR(20)) campaign_id",
        "source": "raw.campaign_stats_data includes base_campaign and id",
        "importance": 3,
        "reason": "The observed prefixed base_campaign values make this plausible, but choosing the wrong key would change all campaign joins and grouping."
      },
      {
        "problem": "The source may contain several network/device records for the same campaign date, which is not reconciled with downstream models described as daily campaign grain.",
        "about": "data",
        "evidence_in_work": "staging.stg_google_ads__campaign_stats: 10,000 rows; marts.google_ads__campaign_report: 9,976 rows",
        "source": "int_google_ads__campaign_cohort_analysis grain: One row per source_relation, campaign_id, and date_day",
        "importance": 3,
        "reason": "Repeated daily keys can make cumulative metrics and cohort row counts operate on segments rather than daily campaigns."
      }
    ],
    "fewer_reason": "Only two grounded concerns were found; the specified staging date filters and monetary casts are present."
  },
  "stg_google_ads__ad_group_history": {
